import{_ as o,r as s,o as p,c,e,a as r,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Введение - October CMS - 3.x","titleTemplate":false,"description":"Настройте контент сайта в точном соответствии с вашими требованиями.","frontmatter":{"subtitle":"Настройте контент сайта в точном соответствии с вашими требованиями."},"headers":[{"level":2,"title":"Структура директорий","slug":"структура-директории","link":"#структура-директории","children":[{"level":3,"title":"Чертежи приложения","slug":"чертежи-приложения","link":"#чертежи-приложения","children":[]},{"level":3,"title":"Чертежи темы","slug":"чертежи-темы","link":"#чертежи-темы","children":[]}]},{"level":2,"title":"Типы чертежей","slug":"типы-чертежеи","link":"#типы-чертежеи","children":[]},{"level":2,"title":"Структура чертежа","slug":"структура-чертежа","link":"#структура-чертежа","children":[]},{"level":2,"title":"Интеграция с мультисайтом","slug":"интеграция-с-мультисаитом","link":"#интеграция-с-мультисаитом","children":[]},{"level":2,"title":"Миграция чертежей","slug":"миграция-чертежеи","link":"#миграция-чертежеи","children":[{"level":3,"title":"Обновление контента","slug":"обновление-контента","link":"#обновление-контента","children":[]},{"level":3,"title":"Распространение контента","slug":"распространение-контента","link":"#распространение-контента","children":[]},{"level":3,"title":"Очистка контента","slug":"очистка-контента","link":"#очистка-контента","children":[]}]}],"relativePath":"3.x/ru/cms/tailor/introduction.md","filePath":"3.x/ru/cms/tailor/introduction.md"}'),d={name:"3.x/ru/cms/tailor/introduction.md"};function u(h,a,g,k,m,b){const n=s("pre-heading"),t=s("post-heading"),l=s("VideoBlockLink");return p(),c("div",null,[e(n),a[0]||(a[0]=r("h1",null,"Введение",-1)),e(t),e(l,{src:"https://www.youtube.com/watch?v=_WMH4mlMdjk",title:"Руководство по Tailor",description:"Это видео описывает, как быстро создать полноценный блог с помощью Tailor.",prompt:"Смотреть руководство"}),a[1]||(a[1]=i(`<p>Tailor — это функция, определяющая файловые структуры контента, используемые вашим сайтом, такие как корпоративный блог или страница команды. Tailor автоматически генерирует пользовательский интерфейс для управления записями в панели администрирования и предоставляет CMS-компоненты для отображения и связывания записей на фронтенде.</p><p>При использовании Tailor вы можете пропустить традиционный процесс разработки плагинов и перейти непосредственно к определению контента. Поля определяются просто как шаблоны чертежей (blueprint), а содержимое хранится в специальных таблицах базы данных. Шаблон чертежа также может определять навигацию и другие модификаторы.</p><h2 id="структура-директории"><a href="#структура-директории" class="header-anchor">#</a> Структура директорий</h2><p>Чертежи — это YAML-файлы, которые по умолчанию находятся в директории <strong>app/blueprints</strong>, а также в директории <strong>themes/.../blueprints</strong> для <a href="./../themes/themes.html">CMS-темы</a>. Размещение чертежей зависит от контекста: <strong>чертежи приложения</strong> доступны глобально, тогда как <strong>чертежи темы</strong> доступны только при выбранной теме.</p><h3 id="чертежи-приложения"><a href="#чертежи-приложения" class="header-anchor">#</a> Чертежи приложения</h3><p>Ниже показан пример структуры директории чертежей. Каждый чертёж может располагаться в любой директории с любым именем файла. Чертежи можно организовывать в подкаталогах любой глубины вложенности.</p><pre class="dir-container"><code><p>├── app
|   └── <code>blueprints</code>  <em>← Чертежи начинаются здесь</em>
|       ├── blog
|       │   └── blog.yaml
|       │   └── author.yaml
|       ├── about
|       │   └── about.yaml
|       ├── wiki
|       │   └── article.yaml</p>
</code></pre><h3 id="чертежи-темы"><a href="#чертежи-темы" class="header-anchor">#</a> Чертежи темы</h3><p>Далее показан пример структуры чертежей внутри темы <strong>demo</strong>. Как и в директории app, чертежи могут располагаться в любой директории с любым именем файла и любой глубиной вложенности. Навигация панели администрирования для этих чертежей будет отображаться только при выбранной теме, что обычно контролируется <a href="./../resources/multisite.html">настройками мультисайта</a>.</p><pre class="dir-container"><code><p>├── themes
|   └── demo
|       ├── <code>blueprints</code>  <em>← Чертежи начинаются здесь</em>
|       │   └── settings.yaml
|       │   └── color-scheme.yaml</p>
</code></pre><h2 id="типы-чертежеи"><a href="#типы-чертежеи" class="header-anchor">#</a> Типы чертежей</h2><p>Свойство <strong>type</strong> чертежа определяет способ его реализации. Доступно несколько типов, и большинство чертежей определяют <a href="./../../element/form-fields.html">поля формы</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td>Entry</td><td>стандартная структура контента с поддержкой черновиков.</td></tr><tr><td>Global</td><td>единственная запись в базе данных, часто используемая для настроек и конфигурации.</td></tr><tr><td>Mixin</td><td>определяет повторно используемые определения полей, которые можно импортировать и смешивать с другими определениями полей.</td></tr></tbody></table></div><p>Каждый тип чертежа подробнее описан в <a href="./blueprints.html">статье о чертежах</a>.</p><h2 id="структура-чертежа"><a href="#структура-чертежа" class="header-anchor">#</a> Структура чертежа</h2><div class="custom-block aside"><p>Чертежи полностью переносимы. Они используют внутренние идентификаторы и могут располагаться в любой директории с любым именем файла.</p></div><p>Чертежи определяются с помощью синтаксиса YAML и всегда содержат три идентификатора: уникальный UUID, удобный для пользователя handle и тип чертежа. Имя файла и директория чертежа используются только для организации и не являются идентификаторами. Все остальные свойства определены в соответствующей документации чертежа.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">uuid</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
<span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token key atrule">name</span><span class="token punctuation">:</span> Post

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token comment"># [...]</span>
</code></pre></div><p><strong>Handle</strong> чертежа — это удобочитаемый способ обращения к объекту чертежа. Используя приведённый выше чертёж в качестве примера, мы можем обращаться к записям с помощью handle.</p><div class="custom-block tip"><p>Handle следуют аналогичному соглашению об именовании, что и пространства имён PHP, и могут быть организованы с помощью разделителя обратной косой черты <code>\\</code>.</p></div><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><p><strong>UUID</strong> чертежа — это уникальный идентификатор, используемый, когда чертежи ссылаются на другие чертежи. Например, когда поле ссылается на миксин. При первом создании чертежа можно не указывать UUID — он будет автоматически создан при первой миграции.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">_blog_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">source</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
</code></pre></div><h2 id="интеграция-с-мультисаитом"><a href="#интеграция-с-мультисаитом" class="header-anchor">#</a> Интеграция с мультисайтом</h2><p>Чертежи по умолчанию не используют <a href="./../resources/multisite.html">возможности мультисайта</a>. Для их включения используйте свойство <code>multisite</code>. При включении записи могут быть уникальными для каждого настроенного сайта.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>При включённом мультисайте все поля в чертеже становятся переводимыми. Чтобы сохранить одинаковое значение поля, установите свойство <code>translatable</code> в false. В этом примере при сохранении записи поле <strong>name</strong> будет скопировано на каждый сайт.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
        <span class="token key atrule">translatable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Вы также можете установить значение <strong>sync</strong> для синхронизации записей между сайтами, что полезно для категорий и тегов. При использовании sync каждая запись всегда существует на каждом сайте, хотя содержимое может отличаться.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> sync
</code></pre></div><p>При использовании <a href="./../resources/multisite.html">групп сайтов</a> записи будут распространяться на все сайты в этой группе. Это можно изменить, установив свойство <code>multisite</code> в <strong>all</strong> для синхронизации между всеми сайтами.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> all
</code></pre></div><p>Установка значения <strong>locale</strong> синхронизирует записи со всеми сайтами, имеющими одну и ту же локаль.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> locale
</code></pre></div><h2 id="миграция-чертежеи"><a href="#миграция-чертежеи" class="header-anchor">#</a> Миграция чертежей</h2><p>Чертежи и их структура мигрируются в базе данных в рамках обычного процесса миграции. При ручном изменении файла чертежа следует выполнить команду <code>tailor:migrate</code> для обновления таблиц базы данных.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:migrate
</code></pre></div><div class="custom-block tip"><p>Чертежи кэшируются, когда режим отладки отключён. Команда миграции также может использоваться для очистки кэша чертежей.</p></div><h3 id="обновление-контента"><a href="#обновление-контента" class="header-anchor">#</a> Обновление контента</h3><p>Вы можете удалить весь контент, управляемый Tailor, с помощью команды <code>tailor:refresh</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:refresh
</code></pre></div><p>Для обновления одного чертежа используйте опцию <code>--blueprint</code> и укажите его handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:refresh <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Post&quot;</span>
</code></pre></div><h3 id="распространение-контента"><a href="#распространение-контента" class="header-anchor">#</a> Распространение контента</h3><p>При использовании опции <strong>sync</strong> для мультисайта вы можете ретроактивно распространить записи с помощью команды <code>tailor:propagate</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate
</code></pre></div><p>Для распространения одного чертежа используйте опцию <code>--blueprint</code> и укажите его handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Category&quot;</span>
</code></pre></div><h3 id="очистка-контента"><a href="#очистка-контента" class="header-anchor">#</a> Очистка контента</h3><p>Как правило, Tailor никогда не удаляет столбцы таблиц и контент. Если поле удалено, столбец будет переименован, а не удалён. Например, старое поле <code>content</code> может отображаться в таблице базы данных как <code>x_content_fb418fac</code>. Таблицы для старых чертежей также сохраняются на случай их восстановления.</p><p>Вы можете очистить неиспользуемые столбцы базы данных с помощью команды <code>tailor:prune</code>. Эта команда также удаляет таблицы, у которых больше нет связанного чертежа.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune
</code></pre></div><p>Вы можете очистить только поля с помощью модификатора <code>--fields</code>. Для очистки только таблиц используйте модификатор <code>--tables</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune <span class="token parameter variable">--fields</span>
php artisan tailor:prune <span class="token parameter variable">--tables</span>
</code></pre></div><p>Для очистки одного чертежа используйте опцию <code>--blueprint</code> и укажите его handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Post&quot;</span>
</code></pre></div>`,56))])}const f=o(d,[["render",u]]);export{y as __pageData,f as default};
